"""Verify using digit DP."""

from functools import lru_cache

@lru_cache(maxsize=None)
def dp(pos: int, sum_so_far: int, rem: int, tight: bool) -> int:
    """Count ways to fill remaining positions."""
    if pos == 7:  # 7 digits (0 to 9,999,999)
        return 1 if sum_so_far == 30 and rem == 0 else 0

    limit = 9  # Since upper bound is 9,999,999, all digits can be 0-9
    total = 0
    for d in range(limit + 1):
        new_sum = sum_so_far + d
        if new_sum > 30:
            break
        new_rem = (rem * 10 + d) % 7
        total += dp(pos + 1, new_sum, new_rem, tight and d == limit)
    return total

